static int cmp_point(const void *pa, const void *pb) {
    Point *a = (Point *)pa;
    Point *b = (Point *)pb;
    if (a->x != b->x) return (a->x < b->x) ? -1 : 1;
    if (a->y != b->y) return (a->y < b->y) ? -1 : 1;
    return 0;
}

