    int N;
    if (scanf("%d", &N) != 1) return 0;

    Point *p = (Point *)malloc(sizeof(Point) * N);
    for (int i = 0; i < N; i++) {
        scanf("%lld %lld", &p[i].x, &p[i].y);
    }

    if (N < 3) {
        printf("0\n");
        free(p);
        return 0;
    }

    qsort(p, N, sizeof(Point), cmp_point);

    ll *pow2 = (ll *)malloc(sizeof(ll) * (N + 1));
    ll *invpow2 = (ll *)malloc(sizeof(ll) * (N + 1));
    pow2[0] = 1;
    for (int i = 1; i <= N; i++) pow2[i] = (pow2[i - 1] * 2) % MOD;
    ll inv2 = (MOD + 1) / 2;
    invpow2[0] = 1;
    for (int i = 1; i <= N; i++) invpow2[i] = (invpow2[i - 1] * inv2) % MOD;

    /*
      DP over ordered pairs:
      Let dp[i][j] = total contribution of chains starting at i and ending at j
      (i < j in lexicographic order), where all intermediate vertices are chosen
      so that polygon edges go strictly counterclockwise, and the score factor
      accumulates invpow2[cnt], where cnt is the number of points strictly inside
      the triangle fan pieces added during construction.

      Transition:
      dp[j][k] += dp[i][j] * invpow2[t(i,j,k)]
      for i < j < k and cross(i,j,k) > 0

      Initialization:
      dp[i][j] = 1 for i < j

      Closing:
      For each chain ending ... -> i -> j, if edge j->start closes a convex polygon,
      multiply by invpow2[number of points on/inside the closing triangle contribution].

      A standard equivalent formulation gives:
      answer = sum over all convex polygons of 2^(inside+boundary - vertices)
             = sum over all convex polygons of product over fan triangles of 2^(-pts_in_triangle_exclusive)

      We implement the known O(N^4) DP by counting, for every triple (i,j,k) with i<j<k and ccw,
      the number of points inside triangle (i,j,k) that lie between j and k in ordering split.
    */

    static ll dp[205][205];
    memset(dp, 0, sizeof(dp));

    ll ans = 0;

    for (int s = 0; s < N; s++) {
        memset(dp, 0, sizeof(dp));

        for (int j = s + 1; j < N; j++) dp[s][j] = 1;

        for (int i = s; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                if (dp[i][j] == 0) continue;

                for (int k = j + 1; k < N; k++) {
                    if (cross3(p[i], p[j], p[k]) <= 0) continue;

                    int cnt = 0;
                    for (int t = i + 1; t < k; t++) {
                        if (t == j) continue;
                        ll c1 = cross3(p[i], p[j], p[t]);
                        ll c2 = cross3(p[j], p[k], p[t]);
                        ll c3 = cross3(p[k], p[i], p[t]);
                        if (c1 > 0 && c2 > 0 && c3 > 0) cnt++;
                        else if ((c1 == 0 || c2 == 0 || c3 == 0) && c1 >= 0 && c2 >= 0 && c3 >= 0) cnt++;
                    }

                    ll add = dp[i][j] * invpow2[cnt] % MOD;
                    dp[j][k] += add;
                    if (dp[j][k] >= MOD) dp[j][k] -= MOD;
                }

                if (i != s && cross3(p[i], p[j], p[s]) > 0) {
                    int cnt = 0;
