                        ll c2 = cross3(p[j], p[s], p[t]);
                        ll c3 = cross3(p[s], p[i], p[t]);
                        if (c1 > 0 && c2 > 0 && c3 > 0) cnt++;
                        else if ((c1 == 0 || c2 == 0 || c3 == 0) && c1 >= 0 && c2 >= 0 && c3 >= 0) cnt++;
                    }

                    ans += dp[i][j] * invpow2[cnt] % MOD;
                    if (ans >= MOD) ans -= MOD;
                }
            }
        }
    }

    /* Remove degenerate triangles/collinear cases automatically excluded by strict ccw.
       Polygons counted once by minimal lexicographic vertex as s. */

    printf("%lld\n", ans % MOD);

