public class Main {
    static final long MOD = 998244353L;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Point {
        long x, y;
        int id;
        Point(long x, long y, int id) {
            this.x = x;
            this.y = y;
            this.id = id;
        }
    }

    static long cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static boolean onSegment(Point a, Point b, Point p) {
        if (cross(a, b, p) != 0) return false;
        return Math.min(a.x, b.x) <= p.x && p.x <= Math.max(a.x, b.x)
                && Math.min(a.y, b.y) <= p.y && p.y <= Math.max(a.y, b.y);
    }

    static boolean inOrOnTriangle(Point a, Point b, Point c, Point p) {
        long c1 = cross(a, b, p);
        long c2 = cross(b, c, p);
        long c3 = cross(c, a, p);
        boolean nonNeg = c1 >= 0 && c2 >= 0 && c3 >= 0;
        boolean nonPos = c1 <= 0 && c2 <= 0 && c3 <= 0;
        return nonNeg || nonPos;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        Point[] pts = new Point[N];
        for (int i = 0; i < N; i++) {
            pts[i] = new Point(fs.nextLong(), fs.nextLong(), i);
        }

        long[] pow3 = new long[N + 5];
        pow3[0] = 1;
        for (int i = 1; i < pow3.length; i++) pow3[i] = pow3[i - 1] * 3 % MOD;

        int[][] onSeg = new int[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) if (i != j) {
                int cnt = 0;
                for (int p = 0; p < N; p++) {
                    if (onSegment(pts[i], pts[j], pts[p])) cnt++;
                }
                onSeg[i][j] = cnt;
            } else {
                onSeg[i][j] = 1;
            }
        }

        int[][][] triCnt = new int[N][N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) if (j != i) {
                for (int k = 0; k < N; k++) if (k != i && k != j) {
                    if (cross(pts[i], pts[j], pts[k]) == 0) continue;
                    int cnt = 0;
                    for (int p = 0; p < N; p++) {
                        if (inOrOnTriangle(pts[i], pts[j], pts[k], pts[p])) cnt++;
                    }
                    triCnt[i][j][k] = cnt;
                }
            }
        }

        long ans = 0;

        for (int root = 0; root < N; root++) {
            ArrayList<Point> list = new ArrayList<>();
            for (int j = 0; j < N; j++) if (j != root) {
                if (pts[j].y > pts[root].y || (pts[j].y == pts[root].y && pts[j].x > pts[root].x)) {
                    list.add(pts[j]);
                }
            }

            list.sort((p1, p2) -> {
                long cr = cross(pts[root], p1, p2);
                if (cr != 0) return cr > 0 ? -1 : 1;
                long d1 = (p1.x - pts[root].x) * (p1.x - pts[root].x) + (p1.y - pts[root].y) * (p1.y - pts[root].y);
                long d2 = (p2.x - pts[root].x) * (p2.x - pts[root].x) + (p2.y - pts[root].y) * (p2.y - pts[root].y);
                return Long.compare(d1, d2);
            });

            int m = list.size();
            int[] id = new int[m];
            for (int i = 0; i < m; i++) id[i] = list.get(i).id;

            for (int s = 0; s < m; s++) {
                long[] dp = new long[m];
                dp[s] = 1;
                for (int j = s; j < m; j++) {
                    if (dp[j] == 0) continue;
                    for (int k = j + 1; k < m; k++) {
                        long cr = cross(pts[root], pts[id[j]], pts[id[k]]);
                        if (cr <= 0) continue;
                        long cr2 = cross(pts[id[j]], pts[id[k]], pts[root]);
                        if (cr2 <= 0) continue; // same as above for ccw triangle
                        // number of points contributed by triangle(root, j, k), excluding segment(root, j) and vertices j,k
                        int add = triCnt[root][id[j]][id[k]] - onSeg[root][id[j]] - 2;
                        if (add < 0) add = 0;
                        dp[k] = (dp[k] + dp[j] * pow3[add]) % MOD;
                    }
                }
                for (int t = s + 1; t < m; t++) {
                    ans += dp[t];
                    if (ans >= MOD) ans -= MOD;
                }
            }
        }

        System.out.println(ans % MOD);
    }
}

