                if ((pts[j] - pts[i]).cross(pts[k] - pts[i]) >= 0) cnt++;
            }
            sum_pow = (sum_pow + pow2[cnt]) % MOD;
        }
    }
    int64 ans = (pow2[N] - (sum_pow - N * pow2[N-1] % MOD + MOD) % MOD + MOD) % MOD;
    // Remove subsets of size 0,1,2
    ans = (ans - 1 + MOD) % MOD; // empty
    ans = (ans - N + MOD) % MOD; // size 1
    ans = (ans - (int64)N*(N-1)/2 % MOD + MOD) % MOD; // size 2
    cout << ans % MOD << "\n";
    return 0;
}

