#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;

struct Point {
    long long x, y;
};

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

long long cross(const Point& a, const Point& b, const Point& c) {
    // (b-a) x (c-a)
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<Point> p(N);
    for (int i = 0; i < N; ++i) cin >> p[i].x >> p[i].y;

    if (N < 3) {
        cout << 0 << '\n';
        return 0;
    }

    // Sort points lexicographically.
    vector<int> ord(N);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int i, int j) {
        if (p[i].x != p[j].x) return p[i].x < p[j].x;
        return p[i].y < p[j].y;
    });

    vector<Point> q(N);
    for (int i = 0; i < N; ++i) q[i] = p[ord[i]];
    p.swap(q);

    // Precompute powers of 2.
    vector<long long> pw2(N + 1);
    pw2[0] = 1;
    for (int i = 1; i <= N; ++i) pw2[i] = pw2[i - 1] * 2 % MOD;

    // inside[i][j] for i<j:
    // number of points k with i<k<j and cross(p[i], p[j], p[k]) > 0
    vector<vector<int>> inside(N, vector<int>(N, 0));
    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            int cnt = 0;
            for (int k = i + 1; k < j; ++k) {
                if (cross(p[i], p[j], p[k]) > 0) ++cnt;
            }
            inside[i][j] = cnt;
        }
    }

    // DP:
    // dp[i][j] = total weight of convex chains starting at i, ending at j (i<j),
    // where weight already includes contributions of chosen intermediate vertices
    // and excludes points strictly inside the polygon-so-far by factor 2^{-cnt}.
    //
    // Transition:
    // start with edge i->j as chain of 2 vertices: dp[i][j] += 1
    // extend k->j to k->i->j? Easier in increasing j:
    //
    // Standard polygon counting by left-turn chains:
    // f[a][b] = sum over chains ending a,b.
    // Extend by c>b if cross(a,b,c)>0.
    //
    // For a completed polygon with first vertex s and last edge a->b, closing b->s,
    // total interior count can be decomposed by triangle additions using inside[][].
    //
    // We do DP per starting vertex s.
    long long ans = 0;
    long long inv2 = modpow(2, MOD - 2);

    for (int s = 0; s < N; ++s) {
        vector<vector<long long>> dp(N, vector<long long>(N, 0));

        for (int j = s + 1; j < N; ++j) {
            dp[s][j] = 1; // chain s -> j
        }

        for (int a = s; a < N; ++a) {
            for (int b = a + 1; b < N; ++b) {
                long long cur = dp[a][b];
                if (!cur) continue;

                // Try closing polygon s ... a -> b -> s
                if (a != s && cross(p[a], p[b], p[s]) > 0) {
                    // Number of points strictly inside added by triangulation:
                    // sum inside of triangles (s, prev, next) was accumulated in transitions.
                    // Closing contributes points in triangle (s,a,b): inside count = inside[a][b] relative to s?
                    //
                    // We need number of points inside/on boundary of final convex hull.
                    // For this triangulation with increasing indices and left turns,
                    // each transition a,b->c adds points inside triangle (s,b,c):
                    // cnt = number of points t with s<t<c in triangle.
                    //
                    // A simpler O(N^4) exact count for closure: for each polygon counted by DP impossible.
                    // Instead use known decomposition:
                    // points strictly inside triangle (s,a,b) among indices in (a,b) and above ab,
                    // plus points between s,a and above sa, etc., already handled.
                    //
                    // To keep correctness, we redesign transition accumulation with g.
                }

                for (int c = b + 1; c < N; ++c) {
                    if (cross(p[a], p[b], p[c]) <= 0) continue;

                    // Added forbidden points are those strictly inside triangle (s,b,c)
                    // among indices (b,c) that lie to the left of line b->c and to the right of s->c etc.
                    // Computing exact count directly:
                    int cnt = 0;
                    for (int t = b + 1; t < c; ++t) {
                        long long c1 = cross(p[s], p[b], p[t]);
                        long long c2 = cross(p[b], p[c], p[t]);
                        long long c3 = cross(p[c], p[s], p[t]);
                        bool pos = (c1 > 0 && c2 > 0 && c3 > 0);
                        bool onok = false;
                        if (!pos) {
                            // boundary of triangle also belongs to hull points count,
                            // but score uses n - |S|, i.e. all non-selected points in/on hull.
                            // In triangulation we only need points strictly inside new triangle,
                            // boundary points on new diagonal shouldn't be double-counted.
                        }
                        if (pos) ++cnt;
                    }

                    long long w = cur * modpow(inv2, cnt) % MOD;
                    dp[b][c] = (dp[b][c] + w) % MOD;
                }
            }
        }

        // The above DP is incomplete for exact problem.
    }

    // Correct approach below:
    //
    // Let F be sum over all convex polygons P of 2^{-(#selected boundary/interior excluded?)}.
    // Equivalent:
    // For every subset T of points, count if its convex hull has all points of T as vertices and no
    // selected non-vertex boundary points. This is hard directly.
    //
    // We use complement counting by choosing a subset A of points and asking whether all chosen points
    // are vertices of their hull. Standard result:
    // answer = sum over convex polygons H of 2^{#(points outside H)} = 2^N * sum_H 2^{-n(H)}.
    // This equals number of subsets whose chosen points are exactly the vertices of their hull.
    //
    // So we count all subsets whose every chosen point is a vertex of conv(subset).
    //
    // DP counts convex polygons with no chosen points inside or on edges except vertices.
    // For each polygon hull containing n total points, any subset choosing exactly its vertices
    // contributes 1, and weighting by 2^{outside} matches original.
    //
    // Standard O(N^4) DP:
    // count empty convex polygons where "empty" means no selected points inside/on edges,
    // but ambient points may exist; weight by 2^{-points in hull}. We can realize by multiplying
    // each triangle extension by 2^{-m}, where m is number of ambient points strictly inside that triangle.
    //
    // Need exact implementation. We'll do direct O(N^4) using triangle point counts.

    // Precompute tri[s][b][c] = number of points strictly inside triangle (s,b,c), for s<b<c and ccw.
    static int tri[85][85][85];
    memset(tri, 0, sizeof(tri));
    for (int s = 0; s < N; ++s) {
        for (int b = s + 1; b < N; ++b) {
            for (int c = b + 1; c < N; ++c) {
                if (cross(p[s], p[b], p[c]) <= 0) continue;
                int cnt = 0;
                for (int t = s + 1; t < c; ++t) {
                    if (t == b) continue;
                    long long c1 = cross(p[s], p[b], p[t]);
                    long long c2 = cross(p[b], p[c], p[t]);
                    long long c3 = cross(p[c], p[s], p[t]);
                    if (c1 > 0 && c2 > 0 && c3 > 0) ++cnt;
                }
                tri[s][b][c] = cnt;
            }
        }
    }

    ans = 0;
    for (int s = 0; s < N; ++s) {
        vector<vector<long long>> dp(N, vector<long long>(N, 0));
        for (int j = s + 1; j < N; ++j) dp[s][j] = 1;

        for (int a = s; a < N; ++a) {
            for (int b = a + 1; b < N; ++b) {
                long long cur = dp[a][b];
                if (!cur) continue;

                // close polygon with edge b -> s
                if (a != s && cross(p[a], p[b], p[s]) > 0) {
                    // weight for points inside final triangle (s,a,b)
                    long long add = cur * modpow(inv2, tri[s][a][b]) % MOD;
                    ans = (ans + add) % MOD;
                }

                for (int c = b + 1; c < N; ++c) {
                    if (cross(p[a], p[b], p[c]) <= 0) continue;
                    long long w = cur * modpow(inv2, tri[a == s ? s : s][b][c]) % MOD;
                    // The triangulation should add triangle (s,b,c)
                    w = cur * modpow(inv2, tri[s][b][c]) % MOD;
                    dp[b][c] = (dp[b][c] + w) % MOD;
                }
            }
        }
    }

    // Multiply by 2^N? No: DP computed sum 2^{-n} over polygons, original asks 2^{n-|S|} with n hull points.
    // Re-interpretation gives exactly count of subsets with all chosen points as hull vertices, which equals
    // 2^N * sum 2^{-n}. Therefore original sum = 2^N * sum 2^{-n} over convex hulls.
    ans = ans * pw2[N] % MOD;

    cout << ans % MOD << '\n';
    return 0;
}
